INSERT INTO "workspaces" VALUES('local_seedy',28,'{"revision":28,"actor":{"id":"local_seedy","name":"交接演示角色1","role":"owner"},"profile":{"name":"小禾同学","grade":"四年级","semester":"上学期","course":"数学","textbook":"演示课程","school":""},"questions":[{"text":"api-verification-1793000810802：图书角新买了 168 本书，平均分给 12 个小组，每组分到多少本？","answer":"14","unit":"本","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","hint":"先想 12 乘几等于 168。","alternative":"把 168 拆成 120 和 48，分别除以 12，10 + 4 = 14。","knowledgeId":"division","difficulty":"基础","steps":["168 ÷ 12 = 14。","答：14本。"],"prerequisites":["整数乘除法"],"id":"2fcf3888-a5dc-4ae8-a73b-17d080b7da20","familyId":"6b1903fc-989c-4784-9ae2-44eeec52a4ad","version":1,"authorId":"local_seedy","createdAt":"2026-10-26T07:46:50.994Z","status":"review"},{"id":"seed-division-1","familyId":"family-division-1","version":1,"text":"图书角新买了 168 本书，平均分给 12 个小组，每组分到多少本？","answer":"14","unit":"本","knowledgeId":"division","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["168 ÷ 12 = 14。","答：14本。"],"hint":"先想 12 乘几等于 168。","alternative":"把 168 拆成 120 和 48，分别除以 12，10 + 4 = 14。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-2","familyId":"family-division-2","version":1,"text":"一盒彩笔有 24 支。288 支彩笔可以装满多少盒？","answer":"12","unit":"盒","knowledgeId":"division","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["288 ÷ 24 = 12。","答：12盒。"],"hint":"用彩笔总数除以每盒的支数。","alternative":"24 × 10 = 240，还剩 48 支，可再装 2 盒，共 12 盒。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-3","familyId":"family-division-3","version":1,"text":"学校有 336 盆花，每 16 盆摆成一排，可以摆多少排？","answer":"21","unit":"排","knowledgeId":"division","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["336 ÷ 16 = 21。","答：21排。"],"hint":"16 × 20 后还差多少？","alternative":"320 ÷ 16 = 20，16 ÷ 16 = 1，合起来是 21。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-4","familyId":"family-division-4","version":1,"text":"一辆小货车每次运 18 箱牛奶，运完 450 箱需要多少次？","answer":"25","unit":"次","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["450 ÷ 18 = 25。","答：25次。"],"hint":"先估算 18 × 20 和 18 × 30。","alternative":"18 × 20 = 360，剩 90 箱需 5 次，一共 25 次。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-5","familyId":"family-division-5","version":1,"text":"把 624 张卡片平均装入 26 个袋子，每袋多少张？","answer":"24","unit":"张","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["624 ÷ 26 = 24。","答：24张。"],"hint":"先试商 20，再计算剩余张数。","alternative":"26 × 20 = 520，剩 104，104 ÷ 26 = 4，所以商是 24。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-6","familyId":"family-division-6","version":1,"text":"工人 15 天做了 375 个零件，平均每天做多少个？","answer":"25","unit":"个","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["375 ÷ 15 = 25。","答：25个。"],"hint":"平均每天的数量 = 总数量 ÷ 天数。","alternative":"300 ÷ 15 = 20，75 ÷ 15 = 5，相加得 25。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-7","familyId":"family-division-7","version":1,"text":"用 32 米长的绳子剪成每段 4 米长的小段，能剪成多少段？","answer":"8","unit":"段","knowledgeId":"division","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["32 ÷ 4 = 8。","答：8段。"],"hint":"求段数，不是剪的次数。","alternative":"4 × 8 = 32，说明有 8 段。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-8","familyId":"family-division-8","version":1,"text":"一批 728 千克苹果，每筐装 28 千克，正好装多少筐？","answer":"26","unit":"筐","knowledgeId":"division","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["728 ÷ 28 = 26。","答：26筐。"],"hint":"28 × 20 = 560，剩余的还能装几筐？","alternative":"728 = 560 + 168，20 + 6 = 26 筐。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-1","familyId":"family-geometry-1","version":1,"text":"一个长方形长 12 厘米、宽 8 厘米，它的周长是多少厘米？","answer":"40","unit":"厘米","knowledgeId":"geometry","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["(12 + 8) × 2 = 40 厘米。","答：40厘米。"],"hint":"长和宽各有两条。","alternative":"12 × 2 + 8 × 2 = 40 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-2","familyId":"family-geometry-2","version":1,"text":"一个长方形长 15 米、宽 6 米，它的面积是多少平方米？","answer":"90","unit":"平方米","knowledgeId":"geometry","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["15 × 6 = 90 平方米。","答：90平方米。"],"hint":"面积用长乘宽，单位是平方米。","alternative":"10 × 6 + 5 × 6 = 90 平方米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-3","familyId":"family-geometry-3","version":1,"text":"一个正方形边长 9 厘米，它的周长是多少厘米？","answer":"36","unit":"厘米","knowledgeId":"geometry","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["9 × 4 = 36 厘米。","答：36厘米。"],"hint":"正方形有四条相等的边。","alternative":"9 + 9 + 9 + 9 = 36 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-4","familyId":"family-geometry-4","version":1,"text":"一块正方形地砖边长 7 分米，面积是多少平方分米？","answer":"49","unit":"平方分米","knowledgeId":"geometry","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["7 × 7 = 49 平方分米。","答：49平方分米。"],"hint":"正方形面积等于边长乘边长。","alternative":"每排 7 个 1 平方分米，共 7 排，是 49 平方分米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-5","familyId":"family-geometry-5","version":1,"text":"一个长方形周长 50 厘米，长 16 厘米，宽是多少厘米？","answer":"9","unit":"厘米","knowledgeId":"geometry","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["50 ÷ 2 − 16 = 9 厘米。","答：9厘米。"],"hint":"先求长与宽的和。","alternative":"两条宽合计 50 − 16 × 2 = 18，宽是 18 ÷ 2 = 9 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-6","familyId":"family-geometry-6","version":1,"text":"一个平角是 180°，其中一个角是 65°，另一个相邻的角是多少度？","answer":"115","unit":"度","knowledgeId":"geometry","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["180 − 65 = 115°。","答：115度。"],"hint"