,{"id":"demo-mistake-1","question":{"id":"demo-original-q-8","familyId":"demo-original-family-8","version":1,"text":"一个正方形边长 9 厘米，它的周长是多少厘米？","answer":"36","unit":"厘米","knowledgeId":"geometry","difficulty":"基础","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["9 × 4 = 36 厘米。","答：36厘米。"],"hint":"正方形有四条相等的边。","alternative":"9 + 9 + 9 + 9 = 36 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},"originalAnswer":"0","evidenceId":"demo-evidence-demo-original-attempt-8"},{"id":"demo-mistake-2","question":{"id":"demo-original-q-9","familyId":"demo-original-family-9","version":1,"text":"一块正方形地砖边长 7 分米，面积是多少平方分米？","answer":"49","unit":"平方分米","knowledgeId":"geometry","difficulty":"巩固","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["7 × 7 = 49 平方分米。","答：49平方分米。"],"hint":"正方形面积等于边长乘边长。","alternative":"每排 7 个 1 平方分米，共 7 排，是 49 平方分米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},"originalAnswer":"0","evidenceId":"demo-evidence-demo-original-attempt-9"}],"events":[{"id":"0f7f560b-d2b5-4b72-a947-11e3d96837aa","action":"question.publish","label":"发布题目","actorId":"local_seedy","createdAt":"2026-10-26T08:28:48.267Z","detail":"已发布，可用于新试卷"},{"id":"ccf3aec9-8c58-4a5e-8e20-34cad72b3d1b","action":"question.review","label":"审核通过","actorId":"local_seedy","createdAt":"2026-10-26T08:28:48.256Z","detail":"已审核通过，可发布"},{"id":"b6735d16-61e8-4c31-9058-10a2c54dbabe","action":"question.submit","label":"提交内容审核","actorId":"local_seedy","createdAt":"2026-10-26T08:28:48.198Z","detail":"已进入待审核，作者不能审核自己的内容"},{"id":"002382bc-72c6-41ff-b99e-689fd32eebd6","action":"question.create","label":"新建题目草稿","actorId":"local_seedy","createdAt":"2026-10-26T08:28:48.188Z","detail":"草稿已保存，需另一位审核人审核后才能发布"},{"