INSERT INTO "workspaces" VALUES('content-ui-qa-1793062314341',4,'{"revision":4,"actor":{"id":"content-ui-qa-1793062314341","name":"交接演示角色12","role":"owner"},"profile":{"name":"小禾同学","grade":"四年级","semester":"上学期","course":"数学","textbook":"演示课程","school":""},"questions":[{"id":"seed-division-1","familyId":"family-division-1","version":2,"taskType":"basic","contextId":"equal-sharing","text":"图书角新买了 168 本书，平均分给 12 个小组，每组分到多少本？","answer":"14","unit":"本","knowledgeId":"division","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["168 ÷ 12 = 14。","答：14本。"],"hint":"先想 12 乘几等于 168。","alternative":"把 168 拆成 120 和 48，分别除以 12，10 + 4 = 14。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-2","familyId":"family-division-2","version":2,"taskType":"basic","contextId":"packing-groups","text":"一盒彩笔有 24 支。288 支彩笔可以装满多少盒？","answer":"12","unit":"盒","knowledgeId":"division","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["288 ÷ 24 = 12。","答：12盒。"],"hint":"用彩笔总数除以每盒的支数。","alternative":"24 × 10 = 240，还剩 48 支，可再装 2 盒，共 12 盒。","prerequisites":["整数乘除法"],"status":"disabled","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-3","familyId":"family-division-3","version":2,"taskType":"basic","contextId":"array-arrangement","text":"学校有 336 盆花，每 16 盆摆成一排，可以摆多少排？","answer":"21","unit":"排","knowledgeId":"division","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["336 ÷ 16 = 21。","答：21排。"],"hint":"16 × 20 后还差多少？","alternative":"320 ÷ 16 = 20，16 ÷ 16 = 1，合起来是 21。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-4","familyId":"family-division-4","version":2,"taskType":"application","contextId":"transport-trips","text":"一辆小货车每次运 18 箱牛奶，运完 450 箱需要多少次？","answer":"25","unit":"次","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["450 ÷ 18 = 25。","答：25次。"],"hint":"先估算 18 × 20 和 18 × 30。","alternative":"18 × 20 = 360，剩 90 箱需 5 次，一共 25 次。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-5","familyId":"family-division-5","version":2,"taskType":"application","contextId":"equal-sharing","text":"把 624 张卡片平均装入 26 个袋子，每袋多少张？","answer":"24","unit":"张","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["624 ÷ 26 = 24。","答：24张。"],"hint":"先试商 20，再计算剩余张数。","alternative":"26 × 20 = 520，剩 104，104 ÷ 26 = 4，所以商是 24。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-6","familyId":"family-division-6","version":2,"taskType":"application","contextId":"average-production","text":"工人 15 天做了 375 个零件，平均每天做多少个？","answer":"25","unit":"个","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["375 ÷ 15 = 25。","答：25个。"],"hint":"平均每天的数量 = 总数量 ÷ 天数。","alternative":"300 ÷ 15 = 20，75 ÷ 15 = 5，相加得 25。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-7","familyId":"family-division-7","version":2,"taskType":"application","contextId":"length-segmentation","text":"用 384 米长的绳子剪成每段 16 米长的小段，能剪成多少段？","answer":"24","unit":"段","knowledgeId":"division","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["384 ÷ 16 = 24。","答：24段。"],"hint":"求段数，用绳子总长度除以每段长度；先试商 20。","alternative":"384 = 320 + 64，320 ÷ 16 + 64 ÷ 16 = 20 + 4 = 24 段。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-8","familyId":"family-division-8","version":2,"taskType":"application","contextId":"weight-packing","text":"一批 728 千克苹果，每筐装 28 千克，正好装多少筐？","answer":"26","unit":"筐","knowledgeId":"division","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["728 ÷ 28 = 26。","答：26筐。"],"hint":"28 × 20 = 560，剩余的还能装几筐？","alternative":"728 = 560 + 168，20 + 6 = 26 筐。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-9","familyId":"family-division-9","version":2,"taskType":"transfer","contextId":"reserve-then-share","text":"社区准备了 552 本练习本，先留出 48 本备用，剩下的平均分给 24 个班。每班分到多少本？","answer":"21","unit":"本","knowledgeId":"division","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["参与分配：552 − 48 = 504 本；每班：504 ÷ 24 = 21 本。","答：21本。"],"hint":"先求真正参与平均分的数量，再除以班级数。","alternative":"先检查 24 × 21 = 504，再加上备用的 48 本，正好是 552 本。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-division-10","familyId":"family-division-10","version":2,"taskType":"transfer","contextId":"equal-budget-exchange","text":"体育组原计划买 18 个篮球，每个 24 元。如果用同样多的钱改买每个 16 元的排球，能买多少个？","answer":"27","unit":"个","knowledgeId":"division","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["总钱数：18 × 24 = 432 元；排球数量：432 ÷ 16 = 27 个。","答：27个。"],"hint":"两种购买方案的总钱数相同，先求原计划的总钱数。","alternative":"把 432 元分成 320 元和 112 元，分别可以买 20 个和 7 个排球，合起来是 27 个。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-1","familyId":"family-geometry-1","version":2,"taskType":"basic","contextId":"rectangle-perimeter","text":"一个长方形长 12 厘米、宽 8 厘米，它的周长是多少厘米？","answer":"40","unit":"厘米","knowledgeId":"geometry","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["(12 + 8) × 2 = 40 厘米。","答：40厘米。"],"hint":"长和宽各有两条。","alternative":"12 × 2 + 8 × 2 = 40 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-2","familyId":"family-geometry-2","version":2,"taskType":"basic","contextId":"rectangle-area","text":"一个长方形长 15 米、宽 6 米，它的面积是多少平方米？","answer":"90","unit":"平方米","knowledgeId":"geometry","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["15 × 6 = 90 平方米。","答：90平方米。"],"hint":"面积用长乘宽，单位是平方米。","alternative":"10 × 6 + 5 × 6 = 90 平方米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-3","familyId":"family-geometry-3","version":2,"taskType":"basic","contextId":"square-perimeter","text":"一个正方形边长 9 厘米，它的周长是多少厘米？","answer":"36","unit":"厘米","knowledgeId":"geometry","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["9 × 4 = 36 厘米。","答：36厘米。"],"hint":"正方形有四条相等的边。","alternative":"9 + 9 + 9 + 9 = 36 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-4","familyId":"family-geometry-4","version":2,"taskType":"application","contextId":"square-area","text":"一块正方形地砖边长 7 分米，面积是多少平方分米？","answer":"49","unit":"平方分米","knowledgeId":"geometry","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["7 × 7 = 49 平方分米。","答：49平方分米。"],"hint":"正方形面积等于边长乘边长。","alternative":"每排 7 个 1 平方分米，共 7 排，是 49 平方分米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-5","familyId":"family-geometry-5","version":2,"taskType":"application","contextId":"inverse-perimeter","text":"一个长方形周长 50 厘米，长 16 厘米，宽是多少厘米？","answer":"9","unit":"厘米","knowledgeId":"geometry","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["50 ÷ 2 − 16 = 9 厘米。","答：9厘米。"],"hint":"先求长与宽的和。","alternative":"两条宽合计 50 − 16 × 2 = 18，宽是 18 ÷ 2 = 9 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-6","familyId":"family-geometry-6","version":2,"taskType":"application","contextId":"perimeter-to-area","text":"一个正方形的周长是 64 厘米，它的面积是多少平方厘米？","answer":"256","unit":"平方厘米","knowledgeId":"geometry","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["边长：64 ÷ 4 = 16 厘米；面积：16 × 16 = 256 平方厘米。","答：256平方厘米。"],"hint":"先用周长除以 4 求边长，再求面积。","alternative":"边长为 16 厘米，面积也可算成 16 × (10 + 6) = 160 + 96 = 256 平方厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-7","familyId":"family-geometry-7","version":2,"taskType":"application","contextId":"area-change","text":"一个长方形长 18 厘米、宽 12 厘米，把长增加 5 厘米、宽保持不变，面积增加多少平方厘米？","answer":"60","unit":"平方厘米","knowledgeId":"geometry","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["增加的面积：5 × 12 = 60 平方厘米。","答：60平方厘米。"],"hint":"增加的部分是一个长 5 厘米、宽 12 厘米的长方形。","alternative":"新面积 23 × 12 = 276 平方厘米，原面积 18 × 12 = 216 平方厘米，相差 60 平方厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-8","familyId":"family-geometry-8","version":2,"taskType":"application","contextId":"inverse-area","text":"一个长方形面积为 96 平方厘米，长 12 厘米，宽是多少厘米？","answer":"8","unit":"厘米","knowledgeId":"geometry","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["96 ÷ 12 = 8 厘米。","答：8厘米。"],"hint":"宽 = 面积 ÷ 长。","alternative":"12 × 8 = 96，所以宽是 8 厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-9","familyId":"family-geometry-9","version":2,"taskType":"transfer","contextId":"same-area-different-boundary","text":"一张长方形纸长 18 厘米、宽 8 厘米，另一张正方形纸边长 12 厘米。两张纸的面积相同，它们的周长相差多少厘米？","answer":"4","unit":"厘米","knowledgeId":"geometry","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["长方形周长：(18 + 8) × 2 = 52 厘米；正方形周长：12 × 4 = 48 厘米；相差：52 − 48 = 4 厘米。","答：4厘米。"],"hint":"面积相同不代表周长相同，要分别计算两张纸的边界长度。","alternative":"两张纸面积都是 144 平方厘米，但周长分别为 52 和 48 厘米，说明面积相同仍可能有不同周长。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-geometry-10","familyId":"family-geometry-10","version":2,"taskType":"transfer","contextId":"fixed-perimeter-reshape","text":"用一根长 64 厘米的铁丝围成一个正方形，再把这根铁丝改围成长 20 厘米的长方形，铁丝没有剩余。长方形的面积是多少平方厘米？","answer":"240","unit":"平方厘米","knowledgeId":"geometry","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["长方形宽：64 ÷ 2 − 20 = 12 厘米；面积：20 × 12 = 240 平方厘米。","答：240平方厘米。"],"hint":"改围前后周长相同。先由周长和长求宽，再求面积。","alternative":"去掉两条长还剩 64 − 20 × 2 = 24 厘米，两条宽各 12 厘米；20 × 12 = 240 平方厘米。","prerequisites":["长度单位与乘法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-1","familyId":"family-multiplication-1","version":2,"taskType":"basic","contextId":"purchase-total","text":"学校买了 16 套课外书，每套 125 元，共需要多少元？","answer":"2000","unit":"元","knowledgeId":"multiplication","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["125 × 16 = 2000 元。","答：2000元。"],"hint":"可以把 16 拆成 8 × 2。","alternative":"125 × 8 × 2 = 1000 × 2 = 2000 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-2","familyId":"family-multiplication-2","version":2,"taskType":"basic","contextId":"equal-groups-total","text":"每箱有 124 支铅笔，买 18 箱一共有多少支？","answer":"2232","unit":"支","knowledgeId":"multiplication","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["124 × 18 = 2232 支。","答：2232支。"],"hint":"把 18 看成 20 − 2，注意乘十位数时的位置。","alternative":"124 × 20 − 124 × 2 = 2480 − 248 = 2232 支。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-3","familyId":"family-multiplication-3","version":2,"taskType":"basic","contextId":"book-set-total","text":"图书馆买了 132 套丛书，每套 15 本，一共有多少本？","answer":"1980","unit":"本","knowledgeId":"multiplication","difficulty":"基础","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["132 × 15 = 1980 本。","答：1980本。"],"hint":"可以把 15 拆成 10 和 5。","alternative":"132 × 10 + 132 × 5 = 1320 + 660 = 1980 本。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-4","familyId":"family-multiplication-4","version":2,"taskType":"application","contextId":"distance-from-rate","text":"一列火车平均每小时行 165 千米，行驶 12 小时共行多少千米？","answer":"1980","unit":"千米","knowledgeId":"multiplication","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["165 × 12 = 1980 千米。","答：1980千米。"],"hint":"路程 = 速度 × 时间，先求 10 小时和 2 小时的路程。","alternative":"165 × 10 + 165 × 2 = 1650 + 330 = 1980 千米。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-5","familyId":"family-multiplication-5","version":2,"taskType":"application","contextId":"purchase-total","text":"每张书桌售价 225 元，学校购买 48 张共需要多少元？","answer":"10800","unit":"元","knowledgeId":"multiplication","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["225 × 48 = 10800 元。","答：10800元。"],"hint":"可以把 48 看成 50 − 2。","alternative":"225 × 50 − 225 × 2 = 11250 − 450 = 10800 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-6","familyId":"family-multiplication-6","version":2,"taskType":"application","contextId":"purchase-total","text":"学校订购 136 套实验材料，每套 28 元，一共需要多少元？","answer":"3808","unit":"元","knowledgeId":"multiplication","difficulty":"巩固","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["136 × 28 = 3808 元。","答：3808元。"],"hint":"把 28 拆成 20 和 8，再把两部分的积相加。","alternative":"136 × 20 + 136 × 8 = 2720 + 1088 = 3808 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-7","familyId":"family-multiplication-7","version":2,"taskType":"application","contextId":"shelf-capacity","text":"每个书架放 108 本书，23 个书架共放多少本？","answer":"2484","unit":"本","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["108 × 23 = 2484 本。","答：2484本。"],"hint":"三位数乘两位数时，注意十位积的位置。","alternative":"108 × 20 + 108 × 3 = 2160 + 324 = 2484 本。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-8","familyId":"family-multiplication-8","version":2,"taskType":"application","contextId":"production-from-rate","text":"一台机器每分钟生产 205 个零件，14 分钟共生产多少个？","answer":"2870","unit":"个","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["205 × 14 = 2870 个。","答：2870个。"],"hint":"先计算乘 10 与乘 4 的两个部分。","alternative":"205 × 10 + 205 × 4 = 2050 + 820 = 2870 个。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-9","familyId":"family-multiplication-9","version":2,"taskType":"transfer","contextId":"total-price-discount","text":"每台小风扇售价 128 元，买满 25 台可从总价中减去 200 元。学校购买 25 台，应付多少元？","answer":"3000","unit":"元","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["未优惠总价：128 × 25 = 3200 元；应付：3200 − 200 = 3000 元。","答：3000元。"],"hint":"先算未优惠的总价，再减去一次总额优惠，不能每台都减 200 元。","alternative":"128 × 25 = 32 × 100 = 3200，再减去总额优惠 200 元，得到 3000 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-multiplication-10","familyId":"family-multiplication-10","version":2,"taskType":"transfer","contextId":"mixed-purchase-budget","text":"学校购买 24 套实验材料，每套 135 元；又购买 18 套模型，每套 120 元。一共需要多少元？","answer":"5400","unit":"元","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["实验材料：135 × 24 = 3240 元；模型：120 × 18 = 2160 元；合计：3240 + 2160 = 5400 元。","答：5400元。"],"hint":"两种物品单价不同，要分别算总价再相加。","alternative":"先算 135 × 20 + 135 × 4，再算 120 × 10 + 120 × 8，把四部分相加也是 5400 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"seed-review-division-1","familyId":"family-review-division-1","version":1,"text":"科技小组有 364 个零件，每 14 个装入一个盒子，可以装满多少盒？","answer":"26","unit":"盒","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创待审核样例","sourceScope":"小学四年级数学演示","steps":["364 ÷ 14 = 26。","验算：26 × 14 = 364。","答：可以装满 26 盒。"],"hint":"先计算 14 × 20，再看剩下多少个零件。","alternative":"364 = 280 + 84，280 ÷ 14 + 84 ÷ 14 = 20 + 6 = 26。","prerequisites":["整数乘除法"],"status":"review","authorId":"seed-author","createdAt":"2026-10-27T00:51:54.341Z"}],"papers":[{"id":"demo-practice-paper","title":"演示针对练习 · 6 题","version":1,"createdAt":"2026-10-23T00:51:54.341Z","questionIds":["demo-practice-q-0","demo-practice-q-1","demo-practice-q-2","demo-practice-q-3","demo-practice-q-4","demo-practice-q-5"],"questions":[{"id":"demo-practice-q-0","familyId":"demo-practice-family-0","version":2,"taskType":"basic","contextId":"equal-sharing","text":"图书角新买了 168 本书，平均分给 12 个小组，每组分到多少本？","answer":"14","unit":"本","knowledgeId":"division","difficulty":"基础","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["168 ÷ 12 = 14。","答：14本。"],"hint":"先想 12 乘几等于 168。","alternative":"把 168 拆成 120 和 48，分别除以 12，10 + 4 = 14。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"demo-practice-q-1","familyId":"demo-practice-family-1","version":2,"taskType":"basic","contextId":"packing-groups","text":"一盒彩笔有 24 支。288 支彩笔可以装满多少盒？","answer":"12","unit":"盒","knowledgeId":"division","difficulty":"基础","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["288 ÷ 24 = 12。","答：12盒。"],"hint":"用彩笔总数除以每盒的支数。","alternative":"24 × 10 = 240，还剩 48 支，可再装 2 盒，共 12 盒。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"demo-practice-q-2","familyId":"demo-practice-family-2","version":2,"taskType":"basic","contextId":"array-arrangement","text":"学校有 336 盆花，每 16 盆摆成一排，可以摆多少排？","answer":"21","unit":"排","knowledgeId":"division","difficulty":"基础","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["336 ÷ 16 = 21。","答：21排。"],"hint":"16 × 20 后还差多少？","alternative":"320 ÷ 16 = 20，16 ÷ 16 = 1，合起来是 21。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},{"id":"demo-practice-q-3","familyId":"demo-practice-family-3","version":2,"taskType":"application","contextId":"transport-trips","text":"一辆小货车每次运 18 箱牛奶，运完 450 箱需要多少次？","answer":"25","unit":"次","knowledgeId":"division","difficulty":"巩固","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["450 ÷ 18 = 25。","答：25次。"],"hint":"先估算 18 × 20 和 18 × 30。","alternative":"18 × 20 = 360，剩 90 箱需 5 次，一共 25 次。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","rev