igest":"337f45cee9f2cf8ecf39cdbf9b3e9348ec5c96337d85f49a05250f82bb09ab60","question":{"id":"seed-multiplication-8","familyId":"family-multiplication-8","version":2,"taskType":"application","contextId":"production-from-rate","text":"一台机器每分钟生产 205 个零件，14 分钟共生产多少个？","answer":"2870","unit":"个","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["205 × 14 = 2870 个。","答：2870个。"],"hint":"先计算乘 10 与乘 4 的两个部分。","alternative":"205 × 10 + 205 × 4 = 2050 + 820 = 2870 个。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},"source":"baseline"},{"id":"seed-multiplication-9@2:73beea4cfc2bf53940798d65852c0c0f3c74be4a89f8572523f7bd7a1ac7e013","questionId":"seed-multiplication-9","version":2,"digest":"73beea4cfc2bf53940798d65852c0c0f3c74be4a89f8572523f7bd7a1ac7e013","question":{"id":"seed-multiplication-9","familyId":"family-multiplication-9","version":2,"taskType":"transfer","contextId":"total-price-discount","text":"每台小风扇售价 128 元，买满 25 台可从总价中减去 200 元。学校购买 25 台，应付多少元？","answer":"3000","unit":"元","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["未优惠总价：128 × 25 = 3200 元；应付：3200 − 200 = 3000 元。","答：3000元。"],"hint":"先算未优惠的总价，再减去一次总额优惠，不能每台都减 200 元。","alternative":"128 × 25 = 32 × 100 = 3200，再减去总额优惠 200 元，得到 3000 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},"source":"baseline"},{"id":"seed-multiplication-10@2:175b610d03accd8d887658b395036b53d2188d06c7da3a0630655ff6164b4de9","questionId":"seed-multiplication-10","version":2,"digest":"175b610d03accd8d887658b395036b53d2188d06c7da3a0630655ff6164b4de9","question":{"id":"seed-multiplication-10","familyId":"family-multiplication-10","version":2,"taskType":"transfer","contextId":"mixed-purchase-budget","text":"学校购买 24 套实验材料，每套 135 元；又购买 18 套模型，每套 120 元。一共需要多少元？","answer":"5400","unit":"元","knowledgeId":"multiplication","difficulty":"挑战","source":"小禾教研原创演示题 · 非教材授权题库","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["实验材料：135 × 24 = 3240 元；模型：120 × 18 = 2160 元；合计：3240 + 2160 = 5400 元。","答：5400元。"],"hint":"两种物品单价不同，要分别算总价再相加。","alternative":"先算 135 × 20 + 135 × 4，再算 120 × 10 + 120 × 8，把四部分相加也是 5400 元。","prerequisites":["整数乘除法"],"status":"published","authorId":"seed-author","reviewerId":"seed-reviewer","reviewNote":"演示题解已样例校核，正式教材范围待教研确认。","createdAt":"2026-10-01T08:00:00.000Z"},"source":"baseline"},{"id":"seed-review-division-1@1:01bbea8568875592de7c2ebece16b52e1a1eddacdb4618b671e193129c7425dd","questionId":"seed-review-division-1","version":1,"digest":"01bbea8568875592de7c2ebece16b52e1a1eddacdb4618b671e193129c7425dd","question":{"id":"seed-review-division-1","familyId":"family-review-division-1","version":1,"text":"科技小组有 364 个零件，每 14 个装入一个盒子，可以装满多少盒？","answer":"26","unit":"盒","knowledgeId":"division","difficulty":"巩固","source":"小禾教研原创待审核样例","sourceScope":"小学四年级数学演示","steps":["364 ÷ 14 = 26。","验算：26 × 14 = 364。","答：可以装满 26 盒。"],"hint":"先计算 14 × 20，再看剩下多少个零件。","alternative":"364 = 280 + 84，280 ÷ 14 + 84 ÷ 14 = 20 + 6 = 26。","prerequisites":["整数乘除法"],"status":"review","authorId":"seed-author","createdAt":"2026-10-27T00:51:54.341Z"},"source":"baseline"},{"id":"demo-practice-q-0@2:c53b34e5e1ab1f64ff13a8a05454c547f6d8b6572d31085ebf9f09900747213f","questionId":"demo-practice-q-0","version":2,"digest":"c53b34e5e1ab1f64ff13a8a05454c547f6d8b6572d31085ebf9f09900747213f","question":{"id":"demo-practice-q-0","familyId":"demo-practice-family-0","version":2,"taskType":"basic","contextId":"equal-sharing","text":"图书角新买了 168 本书，平均分给 12 个小组，每组分到多少本？","answer":"14","unit":"本","knowledgeId":"division","difficulty":"基础","source":"演示历史 · 非真实学生作答","sourceScope":"小学四年级数学演示 · 知识范围需教研校验","steps":["168 ÷ 12 = 14。","答：14本。"],"hi